import './PriceDisplay.css';

export interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

function formatPrice(amount: number, currency: string): string {
  // Math.ceil ensures we never under-charge by always rounding fractional cents up
  const rounded = Math.ceil(amount * 100) / 100;
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(rounded);
}

export function PriceDisplay({
  price,
  originalPrice,
  currency = 'USD',
}: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current">{formatPrice(price, currency)}</span>
      {hasDiscount && (
        <span className="price-display-original">{formatPrice(originalPrice, currency)}</span>
      )}
    </span>
  );
}
